<?php
/** Specialized selling: raw saved configuration, contextual guidance and one label task. @package Booster_For_WooCommerce/admin */
defined('ABSPATH') || exit;
final class WCJ_Specialized_Selling_Workspace {
 public static function data(){return require __DIR__.'/specialized-selling-groups.php';}
 public static function groups(){return self::data()['groups'];}
 public static function edition(){return WCJ_Booking_Label_Job::edition();}
 public static function allowed($id){$core=WCJ_Job_Store::core();return current_user_can('manage_woocommerce')&&$core&&isset($core->all_modules[$id])&&(!function_exists('wcj_is_module_allowed_by_allowlist')||wcj_is_module_allowed_by_allowlist($id))&&(!wcj_is_module_enabled('modules_by_user_roles')||wcj_check_modules_by_user_roles($id));}
 public static function dependency(){return class_exists('WC_Subscriptions',false)&&function_exists('wcs_get_subscription')&&function_exists('wcs_get_subscription_period_strings')&&function_exists('wcs_get_subscription_ranges')&&function_exists('wcs_get_subscription_period_interval_strings')&&function_exists('wcs_get_users_subscriptions');}
 public static function raw($key){global $wpdb;$r=$wpdb->get_row($wpdb->prepare("SELECT option_value FROM {$wpdb->options} WHERE option_name=%s",$key),ARRAY_A);if($wpdb->last_error){throw new RuntimeException('Saved selling settings could not be read.');}return $r?(string)$r['option_value']:null;}
 public static function flag($raw){return null===$raw?'Not stored':('yes'===$raw?'On':('no'===$raw?'Off':'Unrecognized saved value'));}
 public static function count_projection($raw){if(null===$raw){return 'Not stored; check full settings for its default';}return is_string($raw)&&preg_match('/\A(?:0|[1-9][0-9]{0,8})\z/D',$raw)?'Saved count: '.$raw:'Saved count needs full settings';}
 public static function list_count($raw){if(null===$raw){return 'Not stored';}if(''===$raw){return 'Saved empty';}if(!is_string($raw)||strlen($raw)>16384){return 'Advanced saved selection';}$v=@unserialize($raw,array('allowed_classes'=>false,'max_depth'=>2));if(!is_array($v)||count($v)>128||serialize($v)!==$raw){return 'Advanced saved selection';}foreach($v as $k=>$x){if((!is_string($x)&&!is_int($x))||null!==ReflectionReference::fromArrayElement($v,$k)){return 'Advanced saved selection';}}return count($v).' saved choices; identities remain in full settings';}
 private static function choice($raw,$choices){return null===$raw?'Not stored':(isset($choices[$raw])?$choices[$raw]:'Saved value needs full settings');}
 public static function url(){return admin_url('admin.php?page=wcj-specialized-selling');}
 public static function link($url,$label){return '<a target="_blank" rel="noopener noreferrer" href="'.esc_url($url).'">'.esc_html($label.' (new tab)').'</a>';}
 public static function native_url($g){
  if(!self::allowed($g['module'])||('subscription_customization'===$g['module']&&!self::dependency())){return '';}
  if('email'===$g['surface']){return admin_url('admin.php?page=wc-settings&tab=email'.('yes'===self::raw('wcj_preorders_enabled')?'&section='.$g['email_section']:''));}
  if('product'===$g['surface']){return current_user_can('edit_products')?admin_url('edit.php?post_type=product'):'';}
  return admin_url(wcj_admin_tab_url().'&section='.$g['module'].'&active_tab='.$g['native_tab']);
 }
 public static function entry(){foreach(self::groups() as $g){if(self::allowed($g['module'])){echo '<p><a href="'.esc_url(self::url()).'">Specialized selling: booking labels and distinct selling models</a></p>';return;}}}
 private static function boundary($id){$copy=array(
 'product_bookings'=>'Bookings uses date ranges and per-day prices. Enable the module and configure a product separately; this workspace does neither. Free limits enabling bookings to one product when product settings are saved. Plus and Elite do not apply that same save limit. This is not a capacity or overlapping-reservation system.',
 'preorders'=>'Product selection, access, price, fees, shipping and release notifications are separate. Existing checks can change stock and product flags, schedule events and attempt emails. This workspace does not run them. Free and Plus retain a three-selection interface; Elite has different controls. No deposit, charging, reservation or fulfillment guarantee is implied.',
 'crowdfunding'=>'Configure a goal and dates on each product and place the relevant shortcodes separately. Existing dates can affect purchasing, and progress is calculated from orders. This is not escrow, guaranteed funding or an automatic refund service.',
 'product_by_user'=>'The customer form and My Products actions can create, publish, edit or permanently delete owned products. Saved status and existing role checks matter. Turning this module Off is not a complete stop switch for existing form/account links and product-owner emails. Review those settings separately. This is not a complete vendor payment platform.',
 'subscription_customization'=>'Elite and supported WooCommerce Subscriptions are required. Customer actions can cancel a subscription, add priced items, recalculate totals or change a next-payment date. A note or success message alone is not proof of the transition. This workspace neither reads customer subscriptions nor runs those actions.');return $copy[$id];}
 public static function help($module='',$pick=array()){$ed=self::edition();foreach(self::groups() as $g){if(($module&&$g['module']!==$module)||($pick&&!in_array($g['id'],$pick,true))||empty($g['members'][$ed])||!self::allowed($g['module'])){continue;}echo '<article class="wcj-selling-group" data-selling-group="'.esc_attr($g['id']).'"><h3>'.esc_html($g['label']).'</h3><p>'.esc_html($g['context']).'</p><p>';$url=self::native_url($g);if($url){echo self::link($url,'product'===$g['surface']?'Choose a product to edit':('email'===$g['surface']?'WooCommerce email settings':'Full settings')).' | ';}echo self::link($g['guide'],'Guide: '.$g['label']).'</p>';if('product'===$g['surface']){echo '<p>Use the existing product panel; no product is selected or enabled by this link.</p>';}echo '<details><summary>Settings and surfaces covered</summary><ul>';foreach($g['members'][$ed] as $m){echo '<li>'.esc_html($m['label'].($m['locked']?' (locked in Free; prior saved values may still apply)':'')).'</li>';}echo '</ul></details></article>';}}
 public static function screen_help(){if(!current_user_can('manage_woocommerce')){return;}$page=$_GET['page']??'';$section=$_GET['section']??'';$tab=$_GET['tab']??'';$active=$_GET['active_tab']??'';if(!is_string($page)||!is_string($section)||!is_string($tab)||!is_string($active)){return;}$mod='';$pick=array();
  if('wcj-plugins'===$page&&self::allowed($section)){foreach(self::groups() as $g){if($g['module']===$section&&(!$active||$g['native_tab']===$active)){$pick[]=$g['id'];}}$mod=$section;}
  elseif('wc-settings'===$page&&'email'===$tab&&self::allowed('preorders')){foreach(self::groups() as $g){if('email'===$g['surface']&&$section===($g['email_section']??'')&&!empty($g['members'][self::edition()])){$pick[]=$g['id'];}}$mod='preorders';}
  else{$screen=get_current_screen();if(!$screen||'product'!==$screen->post_type||!in_array($screen->base,array('post','edit'),true)){return;}foreach(self::groups() as $g){if('product'===$g['surface']&&self::allowed($g['module'])&&'yes'===self::raw('wcj_'.$g['module'].'_enabled')){$pick[]=$g['id'];}}}
  if(!$pick){return;}echo '<div class="notice notice-info wcj-selling-context"><p><a href="'.esc_url(self::url()).'">Specialized selling workspace</a>. Help opens separately without changing this screen.</p><details><summary>These selling settings: effects and guidance</summary>';self::help($mod,$pick);echo '</details></div>';
 }
 public static function summaries($id){if(!self::allowed($id)){return array();}$rows=array('Saved module state'=>self::flag(self::raw('wcj_'.$id.'_enabled')));
  if('product_bookings'===$id){$rows['Variable-product price display']=self::flag(self::raw('wcj_product_bookings_price_per_day_variable_products'));$rows['Hide quantity selector']=self::flag(self::raw('wcj_product_bookings_hide_quantity'));$rows['Repeated-output check']=self::flag(self::raw('wcj_product_bookings_check_for_outputted_data'));$rows['Product configuration']='Individual product flags stay in the product editor; no products loaded';}
  elseif('preorders'===$id){$rows['Prevent mixed carts']=self::flag(self::raw('wcj_preorders_prevent_mixed_cart'));$rows['Saved access rule']=self::choice(self::raw('wcj_preorders_access_type'),array('all'=>'All users','registered'=>'Registered users','roles'=>'Selected roles'));if('elite'!==self::edition()){$rows['Selected products']=self::list_count(self::raw('wcj_preorders_enable_products_include'));}$rows['Automatic out-of-stock handling']=self::flag(self::raw('wcj_preorders_auto_enable_outofstock'));$rows['Pre-order fee']=self::flag(self::raw('wcj_preorders_global_fee_enabled'));$rows['Free shipping']=self::flag(self::raw('wcj_preorders_free_shipping'));$rows['Notification choices']=self::list_count(self::raw('wcj_preorders_email_notifications'));}
  elseif('crowdfunding'===$id){$rows['Goals and dates']='Per-product metadata, not a global campaign; no products or orders loaded';$rows['Progress displays']='Existing shortcodes use their own order/status/offset rules';}
  elseif('product_by_user'===$id){$rows['Product status']=self::choice(self::raw('wcj_product_by_user_status'),array('draft'=>'Draft','pending'=>'Pending review','publish'=>'Published','private'=>'Private','future'=>'Scheduled'));$rows['Product type']=self::choice(self::raw('wcj_product_by_user_product_type'),array('simple'=>'Simple','external'=>'External / affiliate'));$rows['Account My Products tab']=self::flag(self::raw('wcj_product_by_user_add_to_my_account'));$rows['Owner email']=self::flag(self::raw('wcj_user_product_email_send'));$rows['Custom taxonomy count']='free'===self::edition()?'One under the Free edition rule':self::count_projection(self::raw('wcj_product_by_user_custom_taxonomies_total'));$rows['Role selections']=self::list_count(self::raw('wcj_product_by_user_user_visibility'));}
  elseif('subscription_customization'===$id){$rows['WooCommerce Subscriptions support']=self::dependency()?'Required WooCommerce Subscriptions features are available on this page; no subscription changes have been tested here':'Required WooCommerce Subscriptions support is not available on this page. Its settings link is unavailable';$rows['Cancellation questionnaire']=self::flag(self::raw('wcj_reason_wcs_cancellation_enable'));$rows['Add to existing subscription']=self::flag(self::raw('wcj_wcs_apes_enable'));$rows['Product subscription options']=self::flag(self::raw('wcj_wcsc_addon_enable'));$rows['Next-payment date option']=self::flag(self::raw('wcj_ws_next_payment_date_enable'));}
  return $rows;
 }
 public static function register(){if(current_user_can('manage_woocommerce')){add_submenu_page('woocommerce','Specialized selling','Specialized selling','manage_woocommerce','wcj-specialized-selling',array(__CLASS__,'render'));}}
 public static function render(){if(!current_user_can('manage_woocommerce')){wp_die('Ask an administrator for access.');}wp_enqueue_style('wcj-specialized-selling',wcj_plugin_url().'/assets/css/admin/wcj-specialized-selling-workspace.css',array(),'1.0');echo '<div class="wrap wcj-selling-workspace"><h1>Specialized selling</h1><p>Change a booking label, then inspect each selling model separately. This workspace does not enable modules or products, create orders, send messages or change subscriptions. Existing site setup may still run when WordPress loads.</p>';
  try{if(self::allowed('product_bookings')){self::form();}$lanes=array('product_bookings'=>'Bookings','preorders'=>'Pre-orders','crowdfunding'=>'Crowdfunding','product_by_user'=>'Customer-submitted products','subscription_customization'=>'Subscription customization');foreach($lanes as $id=>$label){if(!self::allowed($id)){if('subscription_customization'===$id&&'elite'!==self::edition()){echo '<p>Subscription customization is available only in Elite and requires supported WooCommerce Subscriptions.</p>';}continue;}$rows=self::summaries($id);echo '<details class="wcj-selling-section" id="wcj-selling-'.esc_attr($id).'"><summary><h2>'.esc_html($label).'</h2> <span>'.esc_html($rows['Saved module state']).'</span></summary><p>'.esc_html(self::boundary($id)).'</p><section class="wcj-selling-current"><h3>Saved configuration</h3><dl>';foreach($rows as $k=>$v){echo '<div><dt>'.esc_html($k).'</dt><dd>'.esc_html($v).'</dd></div>';}echo '</dl></section>';self::help($id);echo '</details>';}}
  catch(Throwable $e){echo '<p role="alert">'.esc_html($e->getMessage()).'</p>';}echo '</div>';
 }
 private static function form(){$t=self::data()['task'];wp_enqueue_script('wcj-specialized-selling',wcj_plugin_url().'/assets/js/admin/wcj-specialized-selling-workspace.js',array(),'1.0',true);$nonces=array();foreach(WCJ_Booking_Label_Job::OPS as $op){$nonces[$op]=wp_create_nonce('wcj_booking_label_'.$op);}wp_localize_script('wcj-specialized-selling','wcjSpecializedSellingWorkspace',array('url'=>admin_url('admin-ajax.php'),'nonces'=>$nonces,'type'=>'booking'));
  echo '<form class="wcj-booking-label" data-field="date_from"><h2>'.esc_html($t['title']).'</h2><p>'.esc_html($t['intro']).'</p><p>Bookings module: <strong>'.esc_html(self::flag(self::raw('wcj_product_bookings_enabled'))).'</strong>.</p><p>'.esc_html($t['inactive']).'</p><label for="wcj-booking-start-label">Start-date label</label><input id="wcj-booking-start-label" name="value" type="text" disabled aria-describedby="wcj-booking-label-hint"><p id="wcj-booking-label-hint">Plain single-line text. The saved value and your draft are separate.</p><details><summary>Label limits and recovery</summary><p>'.esc_html($t['limit']).'</p><p>'.esc_html($t['recovery']).'</p><p>'.esc_html($t['readback']).'</p></details><p>'.esc_html($t['sample']).' <span class="wcj-selling-example"></span></p><p class="wcj-selling-saved"></p><p class="wcj-selling-status" role="status" aria-live="polite">Loading saved label...</p><button class="button button-primary" type="submit" disabled>Save label</button> <button class="button wcj-selling-restore" type="button" disabled>Restore previous</button> <button class="button wcj-selling-reload" type="button">Discard draft and reload</button><p>'.self::link(admin_url(wcj_admin_tab_url().'&section=product_bookings&active_tab=wcj_bookings_labels_and_messages_tab'),'Full booking settings').' | '.self::link($t['guide'],'Setup guide').'</p></form>';
 }
}
add_action('admin_menu',array('WCJ_Specialized_Selling_Workspace','register'),99);
add_action('admin_notices',array('WCJ_Specialized_Selling_Workspace','screen_help'),42);
